# Check if the graph is Eulerian
def is_eulerian(N, edges):
    from collections import defaultdict

    # Create adjacency list
    adj = defaultdict(list)
    indegree = [0] * (N + 1)
    outdegree = [0] * (N + 1)

    for a, b in edges:
        adj[a].append(b)
        outdegree[a] += 1
        indegree[b] += 1

    # Check if all vertices with non-zero degree are connected
    visited = [False] * (N + 1)

    def dfs(v):
        visited[v] = True
        for neighbor in adj[v]:
            if not visited[neighbor]:
                dfs(neighbor)

    # Find a vertex with non-zero degree
    start_vertex = -1
    for i in range(1, N + 1):
        if outdegree[i] > 0 or indegree[i] > 0:
            start_vertex = i
            break

    if start_vertex == -1:
        return False

    dfs(start_vertex)

    for i in range(1, N + 1):
        if (outdegree[i] > 0 or indegree[i] > 0) and not visited[i]:
            return False

    # Check if in-degree equals out-degree for all vertices
    for i in range(1, N + 1):
        if indegree[i] != outdegree[i]:
            return False

    return True

if is_eulerian(N, edges):
    print("YES")
    for a, b in edges:
        print(a, b)
else:
    print("NO")
